@spec generators_spec  src=tests/specs/generators_spec.lua  loc=636  cases=45
@exercises generators (generators), tuning (tuning)
@surface   generators.glyphOf, generators.parksNotes, generators.parkWindows, generators.continuousTargets, generators.chainDestType, generators.destOf, generators.fieldsFor, generators.retarget, generators.fieldRange, tuning.findTemper, tuning.transposeStep, tuning.stepsBetween, generators.thinCurve

# Intent
  generators.lua: slide glide-in envelope.

# Helpers
  @fn expand(kind, hostRec, params, ctx)  @ 9-11
      -- Kinds run alone here, so the chain state equals the original: stream == host (the chain head).
  @fn slideCtx(nextNote, pbRangeCents)  @ 14-17
      -- A slide host (pitch 60) and a ctx supplying the next same-lane note + pb ceiling.
  @fn slideHost(detune)  @ 18-20
  @fn triangle()  @ 24-30
      -- A loop-closed triangle in the normalized domain (-1 .. +1 .. -1), one QN long.
  @fn pts(rows)  @ 34-40
      -- Curve points positionally: {ppq, val, shape?, tension?}; shape defaults to linear, the one kind
      -- thinCurve is allowed to drop.

# Cases
  @case 'every registered kind carries a glyph, one codepoint, shared with no other kind'  [pure]  @ 47-56
  @case 'glyphOf resolves off the registry, and falls back for a kind the registry has lost'  [pure]  @ 60-64
  @case 'slide glides in: flat hold, slur to the interval, then hand off to tm\'s close'  [pure]  @ 70-81
  @case 'slide interval includes detune (the microtonal offset rides in detune, not pitch)'  [pure]  @ 85-89
  @case 'slide clamps the target to ctx.pbRangeCents (a pb can only bend so far)'  [pure]  @ 93-97
  @case 'slide.target='fixed' is a fixed-cents bend (cents demand, no next-note lookup)'  [pure]  @ 101-106
  @case 'slide.target='next' with no following note yields no delta (carrier untouched)'  [pure]  @ 110-114
  @case 'slide to a unison next note yields no delta (zero interval)'  [pure]  @ 118-122
  @case 'trill tiles the window from its start, alternating host pitch with the stepped note'  [pure]  @ 128-144
  @case 'trill carries host detune verbatim on the return (even) tiles'  [pure]  @ 148-155
  @case 'parksNotes is true for any note-dest kind, false for a continuous kind / husk'  [pure]  @ 161-166
  @case 'parkWindows emits an evType-tagged window per continuous/replace target (note discrete, cc, pb augment)'  [pure]  @ 170-185
  @case 'the ownership predicates ignore bypass: a bypassed chain still parks and still scopes its target'  [pure]  @ 189-199
  @case 'chainDestType demotes a bypassed replace stage to augment, and only that stage'  [pure]  @ 203-213
  @case 'destOf falls back to the registry dest; a dest param overrides it'  [pure]  @ 219-224
  @case 'fieldsFor prepends a Dest row only where the kind can serve more than one target'  [pure]  @ 228-236
  @case 'retarget between dests of equal reference leaves the magnitudes alone'  [pure]  @ 240-245
  @case 'retarget rescales magnitudes by proportion of the dest reference'  [pure]  @ 249-255
  @case 'fieldRange spans both ways for a signed magnitude, one way for an unsigned one'  [pure]  @ 259-265
  @case 'retarget carries a signed magnitude across with its sign intact'  [pure]  @ 269-275
  @case 'parkWindows follows the dest param, not the registry (a retargeted pb kind parks cc)'  [pure]  @ 279-286
  @case 'sine on a cc dest tiles the window with extrema in cc steps, anchored 0 at both ends'  [pure]  @ 292-305
  @case 'velPattern cycles its percent pattern per distinct onset; a chord shares one step'  [pure]  @ 311-326
  @case 'velPattern walks onset order regardless of input order, clamping vel to 1..127'  [pure]  @ 330-340
  @case 'ostinato tracks the sounding pitch across the region, not just the first note'  [pure]  @ 346-358
  @case 'ostinato rests when no region note sounds at the gate onset'  [pure]  @ 362-371
  @case 'ostinato emits one gated note per sounding voice (a chord -> multiple lanes)'  [pure]  @ 375-386
  @case 'chord-stamp rebases the pattern chord onto each member; lane-1 note lands on the trigger'  [pure]  @ 392-415
  @case 'chord-stamp transposes by whole temper steps through ctx, not by raw pitch'  [pure]  @ 419-438
  @case 'chord-stamp fires a chord on every region member (all lanes are triggers)'  [pure]  @ 442-464
  @case 'chord-stamp with no lane-1 note in the pattern is inert (no root to rebase from)'  [pure]  @ 468-479
  @case 'lfo tiles the curve at 1/period QN, mapping each val by offset + scale, edges seeded'  [pure]  @ 485-502
  @case 'lfo maps norm in whatever units the dest counts in -- cents on pb'  [pure]  @ 506-515
  @case 'lfo does not clamp -- the body holds no dest knowledge, and the cc seat clamps'  [pure]  @ 519-528
  @case 'lfo with an empty or lengthless curve is inert (no delta)'  [pure]  @ 532-541
  @case 'thinCurve returns a degenerate curve verbatim -- endpoints are never candidates'  [pure]  @ 547-554
  @case 'thinCurve collapses a collinear linear run to its endpoints'  [pure]  @ 558-565
  @case 'thinCurve drops a spike whose vertical error only meets the tolerance'  [pure]  @ 569-573
  @case 'thinCurve keeps a spike whose vertical error exceeds the tolerance'  [pure]  @ 577-580
  @case 'thinCurve keeps a stepped run whole, collinear though its points are'  [pure]  @ 584-588
  @case 'thinCurve rides a curved point through with its tension intact'  [pure]  @ 592-598
  @case 'thinCurve lets a non-linear point pin its successor as well as itself'  [pure]  @ 602-607
  @case 'thinCurve treats a missing shape as non-linear -- under-thin over silently ramping'  [pure]  @ 611-615
  @case 'thinCurve keeps a stack of coincident points -- a zero-width span has no chord'  [pure]  @ 619-623
  @case 'thinCurve gives a dual-point pair no special protection'  [pure]  @ 627-633

